function render(){ $('team').innerHTML=people.map(p=>`<button class="agent" data-person="${p.i}"><span class="portrait" style="background:${p.color}25">${p.icon}</span><span><b>${p.name}</b><small>${p.role}</small><span class="status">● ${stateNames[p.mode]}</span></span><span class="arrow">↗</span></button>`).join('');$('request-count').textContent=data.requests.length;$('requests').innerHTML=data.requests.length?data.requests.map(r=>`<div class="request"><small>Nico · Entrega de prueba</small><b>Tu equipo terminó la propuesta</b><p>${esc(r.plan)}</p><div class="actions"><button data-approve="${r.id}">Aceptar entrega</button><button class="secondary" data-edit="${r.id}">Editar</button><button class="secondary" data-reject="${r.id}">Pedir revisión</button></div></div>`).join(''):'<div class="empty">Nico reparte el trabajo sin pedirte elegir agentes. Cuando la entrega esté lista, vendrá a presentártela.</div>';$('task-count').textContent=data.tasks.length;$('tasks').innerHTML=data.tasks.length?data.tasks.slice().reverse().map(t=>`<div class="task"><b>${esc(t.text)}</b><small>Nico · ${esc(t.status)}</small>${t.steps?`<div class="steps">${t.steps.map(s=>`<div><span>${s.status==='Completada'?'✓':s.status==='Trabajando'?'●':'○'}</span> ${agents[s.agent].name}: ${esc(s.title)} <small>${esc(s.status)}</small>${s.output?`<p>${esc(s.output)}</p>`:''}</div>`).join('')}</div>`:''}${t.result?`<p>${esc(t.result)}</p>`:''}</div>`).join(''):'<p class="footnote">Escribe lo que quieres lograr. Nico elegirá quién debe hacerlo.</p>';$('activity').innerHTML=data.activity.slice(0,15).map(x=>`<div class="task">${esc(x)}</div>`).join('');save()}
function chat(){const p=people[active];$('chat-name').textContent=p.name+' · '+p.role;$('messages').innerHTML=(data.messages[active].length?data.messages[active]:[{text:active===0?'Dime qué quieres lograr. Recibiré tu orden, elegiré a los agentes y revisaré su entrega.':'Nico organiza mis encargos. Si escribes una misión aquí, se la pasaré para que coordine el trabajo.'}]).map(m=>`<div class="message ${m.user?'user':''}">${esc(m.text)}</div>`).join('');$('messages').scrollTop=$('messages').scrollHeight;const busy=p.mode!=='idle';$('eat').disabled=busy;$('rest').disabled=busy;$('call').disabled=busy}
