function campusRoute(from,to){
 if(Math.hypot(from[0]-to[0],from[1]-to[1])<.01)return[];
 const hub=[0,-6];
 function exit(q){const [x,z]=q;
  if(Math.abs(x)<7&&z>=14){const edge=x<0?-3.6:3.6;return[[...q],[edge,z],[edge,15.2],[0,15.2],[0,13.1],[7.8,13.1],[7.8,-6],hub]}
  if(x>=-8&&x<=-2&&z<-16.5)return[[...q],[-5,z],[-5,-16],[-7.8,-16],[-7.8,-6],hub];
  if(Math.abs(x)<4.7&&z<-9)return[[...q],[0,z],[0,-18.3],[7.8,-18.3],[7.8,-6],hub];
  if(Math.abs(x)<7&&z>=0&&z<=12)return[[...q],[2.7,z],[2.7,1],[0,1],[0,-.8],hub];
  if(Math.abs(x)>8.5){const side=Math.sign(x),doorZ=z>13?16.6:people.filter(p=>Math.sign(p.home[0])===side&&p.home[0]!==0).sort((a,b)=>Math.abs(a.home[1]-z)-Math.abs(b.home[1]-z))[0].home[1];return[[...q],[x,doorZ],[side*7.8,doorZ],[side*7.8,-6],hub]}
  if(Math.abs(x)>4.7)return[[...q],[Math.sign(x)*7.8,z],[Math.sign(x)*7.8,-6],hub];
  return[[...q],[x,-6],hub];
 }
 const points=[...exit(from),...exit(to).reverse()];const result=[];let prev=from;for(const q of points){if(Math.hypot(q[0]-prev[0],q[1]-prev[1])>.01){result.push([...q]);prev=q}}return result;
}
function route(p,target,cb){p.mode='walking';p.timer=0;p.route=campusRoute(p.pos,target);p.after=cb;render()}

function setMode(p,m,seconds=0){p.mode=m;p.timer=seconds;render()}
function announce(s){$('scene-status').textContent=s;log(s);render()}
function choosePlan(text){
 const s=text.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
 const full=/(crear|crea|desarroll|constru|implement|hacer|quiero|proyecto).*(sistema|aplicacion|app\b|software|plataforma|inventario|web|proyecto)/.test(s)||/sistema de |aplicacion de |proyecto de software/.test(s);
 const bug=/error|bug|fallo|corrige|corregir|depur|arregla/.test(s),db=/base de datos|sql|consulta|tablas|entidad|datos|persistencia/.test(s);
 const arch=/arquitectura|arquitecto|componentes|estructura del sistema|diseno tecnico/.test(s);
 const req=/requisito|historias de usuario|casos de uso|investig|busca|compar|analiz|informacion|idea/.test(s);
 const doc=/document|manual|presenta|ppt|informe|redact|escrib|propuesta/.test(s);
 const dev=/program|codigo|implement|funcion|api|backend|frontend|desarroll/.test(s),qa=/prueba|test|calidad|validar|verific/.test(s);
 const chosen=new Set();if(full){[1,3,5,4,6,2].forEach(i=>chosen.add(i))}else{
 if(req)chosen.add(1);if(arch)chosen.add(3);if(db)chosen.add(5);if(dev||bug)chosen.add(4);if(qa||dev||bug||db)chosen.add(6);if(doc)chosen.add(2);
 }
 const titles={0:'Organizar el plan del proyecto',1:'Definir requisitos y criterios de aceptación',3:'Diseñar la arquitectura del sistema',5:'Diseñar el modelo de datos',4:bug?'Diagnosticar y corregir el error':'Implementar las funciones del sistema',6:'Preparar pruebas y verificar requisitos',2:'Documentar la entrega técnica'};
 const ids=[1,3,5,4,6,2].filter(i=>chosen.has(i));if(!ids.length)ids.push(0);
 return ids.map(agent=>({agent,title:titles[agent],status:'Pendiente'}));
}
function send(text,i=0){const t={id:crypto.randomUUID(),text,agent:0,orchestrated:true,status:'En cola',steps:choosePlan(text),cursor:0};data.tasks.push(t);missions.push(t);data.messages[0].push({user:true,text},{text:'Recibí tu misión. Yo organizaré los encargos y te presentaré la entrega. Esta es una simulación por reglas, todavía sin IA.'});if(i!==0)data.messages[i].push({user:true,text},{text:'Pasé tu misión a Nico para que organice al equipo.'});announce('Nueva misión para Nico: '+text);startMission();toast(mission===t?'Nico viene a recibir tu orden.':'Misión en cola. Nico la recibirá al terminar la actual.')}
function startMission(){const p=people[0];if(mission||!missions.length)return;mission=missions.shift();p.job=mission;mission.status='Nico viene a recibir la orden';p.after=null;p.route=[];route(p,[0,6.7],()=>{p.yaw=0;setMode(p,'receiving',2);announce('Nico recibe tu misión y se encarga de organizarla.')})}
