 mission.meetingAgents.forEach((i,k)=>{const w=people[i];w.job=mission;w.after=null;w.timer=0;route(w,[[-2.2,0,2.2][k%3],k<3?16.5:19.5],()=>{w.yaw=k<3?0:Math.PI;setMode(w,'meeting')})});
